/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { ANP, I, Perm, PermutationGroup, Poly, PythonMPQ, QQ, S, Sym, add, cancel, exp, factor, gcd, isAlgebraic, minimalPolynomial, mul, pi, pow, rational } from '../../../src';
import { sympyMatches, sympyStr } from '../../sympy-str';

describe("doctests of sympy.polys.domains.algebraicfield", () => {
  it("Poly(x**2 + sqrt(2))", () => {
    const x = new Sym('x');
    expect(sympyStr(Poly.from(add(pow(2, rational(1, 2)), pow(x, 2)), [], {}))).toBe('Poly(x**2 + (sqrt(2)), x, sqrt(2), domain=\'ZZ\')');
  });
  it("Poly(x**2 + sqrt(2), x)", () => {
    const x = new Sym('x');
    expect(sympyStr(Poly.from(add(pow(2, rational(1, 2)), pow(x, 2)), [x], {}))).toBe('Poly(x**2 + sqrt(2), x, domain=\'EX\')');
  });
  it("Poly(x**2 + sqrt(2), x, extension=True)", () => {
    const x = new Sym('x');
    expect(sympyStr(Poly.from(add(pow(2, rational(1, 2)), pow(x, 2)), [x], { extension: true }))).toBe('Poly(x**2 + sqrt(2), x, domain=\'QQ<sqrt(2)>\')');
  });
  it("Poly(x**2 + 1)", () => {
    const x = new Sym('x');
    expect(sympyStr(Poly.from(add(1, pow(x, 2)), [], {}))).toBe('Poly(x**2 + 1, x, domain=\'ZZ\')');
  });
  it("Poly(x**2 + 1, extension=sqrt(2))", () => {
    const x = new Sym('x');
    expect(sympyStr(Poly.from(add(1, pow(x, 2)), [], { extension: pow(2, rational(1, 2)) }))).toBe('Poly(x**2 + 1, x, domain=\'QQ<sqrt(2)>\')');
  });
  it("factor(x**2 - 2)", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(-2, pow(x, 2)), { deep: false, gaussian: false }))).toBe('x**2 - 2');
  });
  it("factor(x**2 - 2, extension=sqrt(2))", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(-2, pow(x, 2)), { extension: [pow(2, rational(1, 2))], deep: false, gaussian: false }))).toBe('(x - sqrt(2))*(x + sqrt(2))');
  });
  it("factor(x**2 - 2, domain='QQ<sqrt(2)>')", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(-2, pow(x, 2)), { domain: 'QQ<sqrt(2)>', deep: false, gaussian: false }))).toBe('(x - sqrt(2))*(x + sqrt(2))');
  });
  it("factor(x**2 - 2, domain=QQ.algebraic_field(sqrt(2)))", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(-2, pow(x, 2)), { domain: 'QQ<sqrt(2)>', deep: false, gaussian: false }))).toBe('(x - sqrt(2))*(x + sqrt(2))');
  });
  it("factor(p)                         # treats sqrt(2) as a symbol", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(pow(x, 3), mul(-2, x), mul(-2, pow(2, rational(1, 2))), mul(pow(2, rational(1, 2)), pow(x, 2))), { deep: false, gaussian: false }))).toBe('(x + sqrt(2))*(x**2 - 2)');
  });
  it("factor(p, extension=True)", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(pow(x, 3), mul(-2, x), mul(-2, pow(2, rational(1, 2))), mul(pow(2, rational(1, 2)), pow(x, 2))), { extension: [S['true']], deep: false, gaussian: false }))).toBe('(x - sqrt(2))*(x + sqrt(2))**2');
  });
  it("factor(x**2 - 2, extension=True)  # all rational coefficients", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(-2, pow(x, 2)), { extension: [S['true']], deep: false, gaussian: false }))).toBe('x**2 - 2');
  });
  it("cancel((x**2 - 2)/(x - sqrt(2)))", () => {
    const x = new Sym('x');
    expect(sympyStr(cancel(mul(pow(add(x, mul(-1, pow(2, rational(1, 2)))), -1), add(-2, pow(x, 2))), {}))).toBe('(x**2 - 2)/(x - sqrt(2))');
  });
  it("cancel((x**2 - 2)/(x - sqrt(2)), extension=sqrt(2))", () => {
    const x = new Sym('x');
    expect(sympyStr(cancel(mul(pow(add(x, mul(-1, pow(2, rational(1, 2)))), -1), add(-2, pow(x, 2))), { extension: pow(2, rational(1, 2)) }))).toBe('x + sqrt(2)');
  });
  it("gcd(x**2 - 2, x - sqrt(2))", () => {
    const x = new Sym('x');
    expect(sympyStr(gcd(add(-2, pow(x, 2)), add(x, mul(-1, pow(2, rational(1, 2)))), {}))).toBe('1');
  });
  it("gcd(x**2 - 2, x - sqrt(2), extension=sqrt(2))", () => {
    const x = new Sym('x');
    expect(sympyStr(gcd(add(-2, pow(x, 2)), add(x, mul(-1, pow(2, rational(1, 2)))), { extension: pow(2, rational(1, 2)) }))).toBe('x - sqrt(2)');
  });
  it("K.to_sympy(xk * yk)", () => {
    expect(sympyStr(QQ.algebraicField(pow(2, rational(1, 2))).toSympy(new ANP([new PythonMPQ(17n, 1n), new PythonMPQ(30n, 1n)], [new PythonMPQ(1n, 1n), new PythonMPQ(0n, 1n), new PythonMPQ(-2n, 1n)], QQ)))).toBe('17*sqrt(2) + 30');
  });
  it("K.to_sympy(xk + yk)", () => {
    expect(sympyStr(QQ.algebraicField(pow(2, rational(1, 2))).toSympy(new ANP([new PythonMPQ(7n, 1n), new PythonMPQ(5n, 1n)], [new PythonMPQ(1n, 1n), new PythonMPQ(0n, 1n), new PythonMPQ(-2n, 1n)], QQ)))).toBe('5 + 7*sqrt(2)');
  });
  it("K.to_sympy(xk ** 2)", () => {
    expect(sympyStr(QQ.algebraicField(pow(2, rational(1, 2))).toSympy(new ANP([new PythonMPQ(24n, 1n), new PythonMPQ(41n, 1n)], [new PythonMPQ(1n, 1n), new PythonMPQ(0n, 1n), new PythonMPQ(-2n, 1n)], QQ)))).toBe('24*sqrt(2) + 41');
  });
  it("K.to_sympy(xk / yk)", () => {
    expect(sympyStr(QQ.algebraicField(pow(2, rational(1, 2))).toSympy(new ANP([new PythonMPQ(1n, 14n), new PythonMPQ(9n, 7n)], [new PythonMPQ(1n, 1n), new PythonMPQ(0n, 1n), new PythonMPQ(-2n, 1n)], QQ)))).toBe('sqrt(2)/14 + 9/7');
  });
  it("g.is_algebraic", () => {
    expect(sympyStr(isAlgebraic(exp(mul(rational(2, 3), pi, I))))).toBe('True');
  });
  it("minpoly(g, x)", () => {
    const x = new Sym('x');
    expect(sympyStr(minimalPolynomial(exp(mul(rational(2, 3), pi, I)), x, { compose: true, polys: false }))).toBe('x**2 + x + 1');
  });
  it("factor(x**3 - 1, extension=g)", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(-1, pow(x, 3)), { extension: [exp(mul(rational(2, 3), pi, I))], deep: false, gaussian: false }))).toBe('(x - 1)*(x - exp(2*I*pi/3))*(x + 1 + exp(2*I*pi/3))');
  });
  it("factor(p)", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(6, pow(x, 4), mul(-5, pow(x, 2))), { deep: false, gaussian: false }))).toBe('(x**2 - 3)*(x**2 - 2)');
  });
  it("factor(p, domain=K)", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(6, pow(x, 4), mul(-5, pow(x, 2))), { domain: 'QQ<sqrt(2) + sqrt(3)>', deep: false, gaussian: false }))).toBe('(x - sqrt(2))*(x + sqrt(2))*(x - sqrt(3))*(x + sqrt(3))');
  });
  it("factor(p, extension=[sqrt(2), sqrt(3)])", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(6, pow(x, 4), mul(-5, pow(x, 2))), { extension: [pow(2, rational(1, 2)), pow(3, rational(1, 2))], deep: false, gaussian: false }))).toBe('(x - sqrt(2))*(x + sqrt(2))*(x - sqrt(3))*(x + sqrt(3))');
  });
  // a primitive result that no library call returned
  //   primitive_element([sqrt(2), sqrt(3)], x)
  //   => (x**4 - 10*x**2 + 1, [1, 1])
  it.todo("primitive_element([sqrt(2), sqrt(3)], x)");
  it("minpoly(sqrt(2) + sqrt(3), x)", () => {
    const x = new Sym('x');
    expect(sympyStr(minimalPolynomial(add(pow(2, rational(1, 2)), pow(3, rational(1, 2))), x, { compose: true, polys: false }))).toBe('x**4 - 10*x**2 + 1');
  });
  // the arguments do not type-check against the public API
  //   K.ext
  //   => sqrt(2) + sqrt(3)
  it.todo("K.ext");
  it("K.orig_ext", () => {
    expect(sympyMatches([pow(2, rational(1, 2)), pow(3, rational(1, 2))], '(sqrt(2), sqrt(3))')).toBe(true);
  });
  // the arguments do not type-check against the public API
  //   K.discriminant()
  //   => 125
  it.todo("K.discriminant()");
  // the arguments do not type-check against the public API
  //   K.integral_basis(fmt='sympy')
  //   => [1, 1/2 + sqrt(5)/2]
  it.todo("K.integral_basis(fmt='sympy')");
  // the arguments do not type-check against the public API
  //   K.maximal_order()
  //   => Submodule[[2, 0], [1, 1]]/2
  it.todo("K.maximal_order()");
  // the arguments do not type-check against the public API
  //   K.primes_above(11)
  //   => [[ (11, _x**3 + 5*_x**2 + 4*_x - 1) e=1, f=3 ], [ (11, _x**3 - 4*_x**2 - 5*_x - 1) e=1, f=3 ]]
  it.todo("K.primes_above(11)");
  // a result object that did not come from the library
  //   K.galois_group(by_name=True)[0]
  //   => S6TransitiveSubgroups.C6
  it.todo("K.galois_group(by_name=True)[0]");
  it("G.order()", () => {
    expect(sympyStr(PermutationGroup([new Perm([1, 0, 3, 2]), new Perm([2, 3, 0, 1])]).order())).toBe('4');
  });
  it("G.order() (2)", () => {
    expect(sympyStr(PermutationGroup([new Perm([1, 2, 3, 0]), new Perm([3, 2, 1, 0])]).order())).toBe('8');
  });
  it("K", () => {
    expect(sympyStr(QQ.algebraicField(pow(2, rational(1, 2))))).toBe('QQ<sqrt(2)>');
  });
  it("g", () => {
    expect(sympyStr(exp(mul(rational(2, 3), pi, I)))).toBe('exp(2*I*pi/3)');
  });
  it("K (2)", () => {
    expect(sympyStr(QQ.algebraicField(pow(2, rational(1, 2)), pow(3, rational(1, 2))))).toBe('QQ<sqrt(2) + sqrt(3)>');
  });
  it("K (3)", () => {
    expect(sympyStr(QQ.algebraicField(pow(2, rational(1, 2)), pow(3, rational(1, 2))))).toBe('QQ<sqrt(2) + sqrt(3)>');
  });
  it("K (4)", () => {
    expect(sympyStr(QQ.algebraicField(exp(mul(rational(2, 5), pi, I))))).toBe('QQ<exp(2*I*pi/5)>');
  });
  it("K (5)", () => {
    expect(sympyStr(QQ.algebraicField(pow(5, rational(1, 2))))).toBe('QQ<sqrt(5)>');
  });
  it("K (6)", () => {
    expect(sympyStr(QQ.algebraicField(exp(mul(rational(2, 7), pi, I))))).toBe('QQ<exp(2*I*pi/7)>');
  });
});
